// lib/spice-utils/convertSpiceNetlistToString.ts
var convertSpiceNetlistToString = (netlist) => {
  const lines = [];
  lines.push(netlist.title);
  if (netlist.models.size > 0) {
    lines.push(...Array.from(netlist.models.values()));
  }
  for (const component of netlist.components) {
    lines.push(component.toSpiceString());
  }
  if (netlist.optionStatements.length > 0) {
    lines.push(...netlist.optionStatements);
  }
  if (netlist.metadataComments.length > 0) {
    lines.push(...netlist.metadataComments);
  }
  for (const subcircuit of netlist.subcircuits) {
    lines.push(subcircuit.toSpiceString());
  }
  if (netlist.printStatements.length > 0) {
    lines.push(...netlist.printStatements);
  }
  if (netlist.saveStatements.length > 0) {
    lines.push(...netlist.saveStatements);
  }
  if (netlist.controls.length > 0) {
    lines.push(".control");
    lines.push(...netlist.controls);
    lines.push(".endc");
  }
  if (netlist.analysisCommand) {
    const analysisDirective = netlist.analysisCommand.trim().toLowerCase().split(/\s+/)[0];
    const alreadyIncludesAnalysis = lines.some(
      (line) => line.trim().toLowerCase().split(/\s+/)[0] === analysisDirective
    );
    if (!alreadyIncludesAnalysis) {
      lines.push(netlist.analysisCommand);
    }
  }
  lines.push(".END");
  return lines.join("\n");
};

// lib/spice-classes/SpiceNetlist.ts
var SpiceNetlist = class {
  title;
  components;
  nodes;
  controls;
  subcircuits;
  models;
  optionStatements;
  metadataComments;
  analysisCommand;
  printStatements;
  saveStatements;
  constructor(title = "Circuit Netlist") {
    this.title = title;
    this.components = [];
    this.nodes = /* @__PURE__ */ new Set();
    this.controls = [];
    this.subcircuits = [];
    this.models = /* @__PURE__ */ new Map();
    this.optionStatements = [];
    this.metadataComments = [];
    this.analysisCommand = null;
    this.printStatements = [];
    this.saveStatements = [];
  }
  addComponent(component) {
    this.components.push(component);
    for (const node of component.nodes) {
      this.nodes.add(node);
    }
  }
  addSubcircuit(subcircuit) {
    if (this.subcircuits.find((s) => s.name === subcircuit.name)) return;
    this.subcircuits.push(subcircuit);
  }
  get tranCommand() {
    return this.analysisCommand?.trim().toLowerCase().startsWith(".tran") ? this.analysisCommand : null;
  }
  set tranCommand(tranCommand) {
    this.analysisCommand = tranCommand;
  }
  toSpiceString() {
    return convertSpiceNetlistToString(this);
  }
};

