// lib/spice-commands/MOSFETCommand.ts
var MOSFETCommand = class {
  commandName = "mosfet";
  props;
  constructor(props) {
    this.props = props;
  }
  toSpiceString() {
    const {
      name,
      drain,
      gate,
      source,
      substrate,
      model,
      length,
      width,
      drainArea,
      sourceArea,
      drainPerimeter,
      sourcePerimeter,
      drainResistance,
      sourceResistance
    } = this.props;
    let spiceString = `M${name} ${drain} ${gate} ${source} ${substrate} ${model}`;
    const params = {
      L: length,
      W: width,
      AD: drainArea,
      AS: sourceArea,
      PD: drainPerimeter,
      PS: sourcePerimeter,
      NRD: drainResistance,
      NRS: sourceResistance
    };
    Object.entries(params).forEach(([key, value]) => {
      if (value) {
        spiceString += ` ${key}=${value}`;
      }
    });
    return spiceString;
  }
};

