// lib/processors/simple-diode.ts
var getDiodeNodes = (componentPorts, nodeMap) => {
  const anodePort = componentPorts.find(
    (p) => p.name?.toLowerCase() === "anode" || p.port_hints?.includes("anode")
  );
  const cathodePort = componentPorts.find(
    (p) => p.name?.toLowerCase() === "cathode" || p.port_hints?.includes("cathode")
  );
  return {
    positiveNode: nodeMap.get(anodePort?.source_port_id ?? "") || "0",
    negativeNode: nodeMap.get(cathodePort?.source_port_id ?? "") || "0"
  };
};
var processDiodeLikeComponent = ({
  netlist,
  component,
  componentPorts,
  nodeMap,
  modelName,
  modelDefinition
}) => {
  if ("name" in component) {
    const { positiveNode, negativeNode } = getDiodeNodes(
      componentPorts,
      nodeMap
    );
    const diodeCmd = new DiodeCommand({
      name: component.name,
      positiveNode,
      negativeNode,
      model: modelName
    });
    netlist.models.set(modelName, modelDefinition);
    return new SpiceComponent(component.name, diodeCmd, [
      positiveNode,
      negativeNode
    ]);
  }
  return null;
};
var processSimpleDiode = ({
  netlist,
  component,
  componentPorts,
  nodeMap
}) => {
  return processDiodeLikeComponent({
    netlist,
    component,
    componentPorts,
    nodeMap,
    modelName: "D",
    modelDefinition: ".MODEL D D"
  });
};
var processSimpleLed = ({
  netlist,
  component,
  componentPorts,
  nodeMap
}) => {
  return processDiodeLikeComponent({
    netlist,
    component,
    componentPorts,
    nodeMap,
    modelName: "LED",
    modelDefinition: ".MODEL LED D(IS=1e-20 N=2 RS=10 CJO=2p EG=2.1 BV=5 IBV=10u)"
  });
};

